pace-between;gap:12px;padding:12px 0;border-bottom:1px solid #edf1f7;font-size:13px}.row:last-child{border-bottom:0}.row b{color:#687b9c}.value{font-weight:800;text-align:right;color:#163a73}.pill{display:inline-block;padding:5px 9px;border-radius:9px;background:#eaf4ff;color:#0868db;font-size:11px}.green{background:#e5faef;color:#0b9b5a}.red{background:#ffe9ec;color:#c53048}.back{border:0;background:none;color:#fff;font-size:24px;width:32px}.pagehead{display:flex;align-items:center;gap:8px;margin:-2px 0 14px}.pagehead h2{margin:0;font-size:20px}.qrbox{background:#f8fbff;border:1px solid #dce8f7;border-radius:16px;padding:16px;text-align:center}.scan{width:100%;border:0;border-radius:13px;background:#0868db;color:#fff;padding:15px;font-size:16px;font-weight:800}.stop{background:#d9435b;margin-top:9px}.msg{margin-top:10px;background:#eef6ff;padding:11px;border-radius:11px;font-size:12px;font-weight:700;text-align:center}.hidden{display:none!important}#reader{margin:12px auto;width:100%;overflow:hidden;border-radius:14px}.history{width:100%;border-collapse:collapse;font-size:11px}.history th,.history td{padding:9px 4px;border-bottom:1px solid #e7edf5;text-align:left}.rule{display:flex;gap:12px;align-items:flex-start;padding:13px 0;border-bottom:1px solid #edf1f7;font-size:13px;line-height:1.45}.num{width:29px;height:29px;flex:0 0 29px;border-radius:50%;background:#0868db;color:#fff;display:grid;place-items:center;font-weight:800}.contact{display:flex;align-items:center;gap:13px;padding:14px;border:1px solid #e2ebf7;border-radius:14px;background:#fff;margin-bottom:10px;text-decoration:none;color:#17376e}.contact .ico{width:42px;height:42px;border-radius:12px;background:#eaf4ff;display:grid;place-items:center;font-size:22px}.contact b{display:block;margin-bottom:3px}.contact small{color:#6b7d9e}.bottom{position:fixed;z-index:30;bottom:0;left:50%;transform:translateX(-50%);width:min(480px,100%);height:70px;background:#fff;border-top:1px solid #dfe8f5;display:grid;grid-template-columns:repeat(4,1fr);box-shadow:0 -5px 20px rgba(0,50,120,.08)}.nav{border:0;background:none;color:#7183a1;font-size:10px;font-weight:700}.nav span{display:block;font-size:21px;margin-bottom:3px}.nav.active{color:#0868db}.banner{margin-top:14px;border-radius:16px;overflow:hidden;position:relative;background:#dbeeff;height:120px}.banner img{width:100%;height:100%;object-fit:cover;opacity:.92}.banner div{position:absolute;inset:0;display:flex;align-items:flex-end;padding:14px;color:#fff;font-weight:800;font-size:18px;background:linear-gradient(transparent,rgba(0,45,110,.65))}.empty{text-align:center;color:#7183a1;padding:18px}.notice{padding:12px;border-radius:12px;background:#f2f8ff;border-left:4px solid #0868db;margin-bottom:9px}.notice b{display:block;margin-bottom:4px}.notice small{color:#6c7d9b}
