<script>
const initialQR=<?php echo json_encode($qr,JSON_UNESCAPED_SLASHES); ?>;let scanner=null,current=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function showScreen(id){document.querySelectorAll('.screen').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.screen===id));window.scrollTo({top:0,behavior:'smooth'});if(id==='attendance')loadMe();}
function setText(id,v){const e=document.getElementById(id);if(e)e.textContent=v??'—';}
function render(data){current=data;const m=data.member||{};const initials=(m.name||'AR').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();['avatar','profileAvatar'].forEach(id=>setText(id,initials));setText('dashName',m.name||'Member');setText('dashId','Member ID: '+(m.member_id||'—'));setText('dashStatus',m.status||'Active');setText('dashValid',m.validity_date||'—');setText('profileName',m.name||'Member');setText('profileId','Member ID: '+(m.member_id||'—'));setText('profileStatus',m.status||'Active');setText('seatNo',m.seat_no||'Not Assigned');setText('seatStatus',m.seat_no?'Active':'Not Assigned');setText('seatType',m.seat_no?'Assigned':'—');setText('seatShift',m.seat_shift||m.shift||'Full Day');setText('seatValid',m.validity_date||'—');const due=Number(m.fee_due||0);setText('dashSeat',m.seat_no||'Not Assigned');setText('dashSeatShift',m.seat_shift||m.shift||'—');setText('dashFee',due>0?'₹'+due.toLocaleString('en-IN'):'Paid');setText('dashFeeText',due>0?'Payment pending':'No pending fee');document.getElementById('dashFee').style.color=due>0?'#c53048':'#0b9b5a';
 document.getElementById('profileRows').innerHTML=[['Mobile',m.phone],['Email',m.email],['Course / Exam',m.course||m.membership_plan],['Joining Date',m.joining_date],['Valid Till',m.validity_date],['Seat No.',m.seat_no||'Not Assigned'],['Membership',m.membership_plan],['Address',m.address||'Baikunthpur, M.P.']].map(r=>`<div class="row"><b>${esc(r[0])}</b><span class="value">${esc(r[1]||'—')}</span></div>`).join('');
 const rows=data.attendance||[];document.getElementById('history').innerHTML=rows.length?rows.map(r=>`<tr><td>${esc(r.attendance_date)}</td><td>${esc(r.check_in_time||'—')}</td><td>${esc(r.check_out_time||'—')}</td><td><span class="pill">${esc(r.status||'')}</span></td></tr>`).join(''):'<tr><td colspan="4" class="empty">No attendance records yet.</td></tr>';const t=data.today||{};setText('todayIn',t.check_in_time||'—');setText('todayOut',t.check_out_time||'—');setText('todayStatus',t.status||'Not Marked');if(t.check_in_time&&!t.check_out_time)document.getElementById('msg').textContent='Checked In at '+t.check_in_time+'. Scan again when leaving.';else if(t.check_out_time)document.getElementById('msg').textContent='Today attendance completed.';}
function renderNotifications(list){const box=document.getElementById('notifications');if(!Array.isArray(list)||!list.length){box.innerHTML='<div class="empty">No new notifications.</div>';return;}box.innerHTML=list.slice(0,5).map(n=>`<div class="notice"><b>${esc(n.icon||'🔔')} ${esc(n.title||'Notification')}</b><div style="font-size:12px;line-height:1.4">${esc(n.message||'')}</div><small>${esc(n.created_at||'')}</small></div>`).join('');}
async function loadNotifications(){try{const r=await fetch('member_api.php?action=notifications',{cache:'no-store'}),d=await r.json();if(d.success)renderNotifications(d.notifications||[]);}catch(e){console.error(e)}}
async function loadMe(){try{const r=await fetch('member_api.php?action=me',{cache:'no-store'}),d=await r.json();if(!d.success){location.href='member_login.php';return}render(d)}catch(e){console.error(e);if(document.getElementById('msg'))document.getElementById('msg').textContent='Could not load member data.'}}
function extractToken(text){try{const u=new URL(text);return u.searchParams.get('qr')||u.searchParams.get('token')||(u.searchParams.get('attendance')==='1'?'AR_LIBRARY_ATTENDANCE_V1':'')}catch(e){return text.trim()}}
async function sendScan(token){if(token!=='AR_LIBRARY_ATTENDANCE_V1'){document.getElementById('msg').textContent='Invalid AR Library attendance QR.';return}document.getElementById('msg').textContent='QR verified. Getting your location...';if(!navigator.geolocation){document.getElementById('msg').textContent='Location is not supported on this device.';return}navigator.geolocation.getCurrentPosition(async p=>{const fd=new FormData();fd.append('token',token);fd.append('latitude',p.coords.latitude);fd.append('longitude',p.coords.longitude);fd.append('accuracy',p.coords.accuracy||'');try{const r=await fetch('attendance_api.php?action=scan_attendance',{method:'POST',body:fd,cache:'no-store'}),d=await r.json();document.getElementById('msg').textContent=d.message||'Attendance updated';if(d.success)loadMe()}catch(e){document.getElementById('msg').textContent='Could not connect to attendance server.'}},e=>{document.getElementById('msg').textContent=e.code===1?'Location permission denied.':e.code===2?'Location unavailable. Turn on GPS.':'Could not get location. Try again.'},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}
async function onScanSuccess(text){const token=extractToken(text);await stopScanner();await sendScan(token)}
async function startScanner(){document.getElementById('scanBtn').classList.add('hidden');document.getElementById('reader').classList.remove('hidden');document.getElementById('stopBtn').classList.remove('hidden');document.getElementById('msg').textContent='Camera starting...';try{if(typeof Html5Qrcode==='undefined')throw new Error('QR library not loaded');scanner=new Html5Qrcode('reader');const cfg={fps:10,qrbox:{width:230,height:230}};try{await scanner.start({facingMode:{exact:'environment'}},cfg,onScanSuccess,()=>{})}catch(e){const cams=await Html5Qrcode.getCameras();if(!cams.length)throw e;await scanner.start(cams[0].id,cfg,onScanSuccess,()=>{})}document.getElementById('msg').textContent='Point camera at office QR.'}catch(e){console.error(e);document.getElementById('msg').textContent='Camera could not start. Allow camera permission and try again.';await stopScanner()}}
async function stopScanner(){if(scanner){try{await scanner.stop()}catch(e){}try{scanner.clear()}catch(e){}scanner=null}document.getElementById('reader').classList.add('hidden');document.getElementById('stopBtn').classList.add('hidden');document.getElementById('scanBtn').classList.remove('hidden')}
async function logout(){try{await fetch('member_api.php?action=logout',{cache:'no-store'})}catch(e){}location.href='member_login.php'}
loadMe();loadNotifications();if(initialQR)setTimeout(()=>sendScan(initialQR),500);
</script></body></html>
